  var mensajeSalida = "";
  document.addEventListener("click", (ev) => {
    const btn = ev.target instanceof Element ? ev.target.closest("button, input[type=submit]") : null;
    if (!btn || btn.disabled || !btn.form) return;
    if ((btn.getAttribute("type") || "submit") !== "submit") return;
    const form = btn.form;
    if (form.method === "dialog") return;
    ev.preventDefault();
    if (!form.checkValidity()) {
      form.reportValidity();
      return;
    }
    let envio;
    try {
      envio = new SubmitEvent("submit", { bubbles: true, cancelable: true, submitter: btn });
    } catch {
      envio = new Event("submit", { bubbles: true, cancelable: true });
    }
    form.dispatchEvent(envio);
  }, true);
  document.addEventListener("click", (ev) => {
    if (ev.defaultPrevented || ev.button !== 0 || ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey) return;
    const a = ev.target instanceof Element ? ev.target.closest('a[href^="#/"]') : null;
    if (!a || a.target && a.target !== "_self") return;
    ev.preventDefault();
    const destino = a.getAttribute("href");
    if (location.hash === destino) window.dispatchEvent(new HashChangeEvent("hashchange"));
    else location.hash = destino;
  });
